  const SCI = { tr: `\nfrom sklearn.linear_model import LinearRegression, Lasso\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.model_selection import GridSearchCV, TimeSeriesSplit, KFold\nfrom sklearn.exceptions import ConvergenceWarning\nwarnings.filterwarnings("always", category=ConvergenceWarning)   # yakınsama uyarısı görünür kalır\nXe, Xt, ye, yt = egitim[ozellikler], test[ozellikler], egitim["hedef"], test["hedef"]\nizgara = np.logspace(-4, 0.5, 60)                                # denenecek λ değerleri`, en: `\nfrom sklearn.linear_model import LinearRegression, Lasso\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.model_selection import GridSearchCV, TimeSeriesSplit, KFold\nfrom sklearn.exceptions import ConvergenceWarning\nwarnings.filterwarnings("always", category=ConvergenceWarning)   # convergence warnings stay visible\nXe, Xt, ye, yt = train[features], test[features], train["target"], test["target"]\ngrid = np.logspace(-4, 0.5, 60)                                  # λ values to try` };
  const IS = { tr: D.INFX.tr + SCI.tr, en: D.INFX.en + SCI.en };
  const U8A = { tr: IS.tr + `\narama = GridSearchCV(make_pipeline(StandardScaler(), Lasso(max_iter=50000)), {"lasso__alpha": izgara},\n                     cv=KFold(5, shuffle=True, random_state=1), scoring="neg_mean_squared_error")\narama.fit(Xe, ye)                                                # ölçekleyici her katta yeniden kurulur\ncv_hata = np.sqrt(-arama.best_score_)\nprint("Seçilen λ:", round(arama.best_params_["lasso__alpha"], 4), "| çapraz doğrulama kök HKO:", round(cv_hata, 3))`, en: IS.en + `\nsearch = GridSearchCV(make_pipeline(StandardScaler(), Lasso(max_iter=50000)), {"lasso__alpha": grid},\n                      cv=KFold(5, shuffle=True, random_state=1), scoring="neg_mean_squared_error")\nsearch.fit(Xe, ye)                                               # the scaler is refitted in each fold\ncv_err = np.sqrt(-search.best_score_)\nprint("Chosen λ:", round(search.best_params_["lasso__alpha"], 4), "| cross-validation RMSE:", round(cv_err, 3))` };
